// Vazirmatn (Arabic/Persian subset, weights 400 & 600) embedded as data URIs so
// the Studio renders Persian text in Vazirmatn with NO runtime font request —
// consistent with the self-contained (auto-updates off) deployment. The
// unicode-range limits Vazirmatn to Arabic-script codepoints, so Latin text
// still uses the Studio's Latin font. Source: @fontsource/vazirmatn 5.2.8.
/* eslint-disable */
export const vazirmatnFontCss = `
@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-display: swap;
  font-weight: 400;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0600-06FF,U+0750-077F,U+0870-088E,U+0890-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC;
}
@font-face {
  font-family: 'Vazirmatn';
  font-style: normal;
  font-display: swap;
  font-weight: 600;
  src: url(data:font/woff2;base64,) format('woff2');
  unicode-range: U+0600-06FF,U+0750-077F,U+0870-088E,U+0890-0891,U+0897-08E1,U+08E3-08FF,U+200C-200E,U+2010-2011,U+204F,U+2E41,U+FB50-FDFF,U+FE70-FE74,U+FE76-FEFC;
}
`
